import { basename } from 'node:path';
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { COMMENT_CHECKABLE, commentOnly } from '../../../../engine/checks/helpers/code-scanning.mjs';

// The write-surface gate for the improve-comments pass. Its skill bounds every edit
// to comments in code files and to `README.md` documents; the pass runs unattended
// and writes the repo's OWN SOURCE — the one surface no other tidy-repo task
// touches — so the boundary needs a machine guarantee rather than a prose request.
//
// THE PERMISSION IS READ, NEVER ASSERTED. A file passes because its code is
// identical once the comments are stripped from both sides, not because the run
// says it only touched comments. That is the whole point: a run that quietly
// renamed a variable while "improving comments" is exactly what this catches, and
// a run cannot talk its way past a text comparison.
//
// THREE SHAPES FAIL, and each is deliberate rather than an oversight:
//   - a file whose language `commentOnly` cannot parse counts as code, so a comment
//     edit in one reds the run. Answering "I could not look" as a pass would make
//     the gate silently narrower than the languages a repo actually holds;
//   - an ADDED or DELETED code file is never comment-only, whatever it holds — a
//     whole file is a whole file, and this pass does not add or remove them;
//   - a DELETED `README.md` is not an improvement to a README. Modifying one is the
//     pass's business; deciding a document should not exist is not.
//
// RELEVANCE IS THE PINNED COMMIT SUBJECT, the same self-gating shape
// claudinite-growth's capture gate uses: the run marks itself, so this rule can run
// everywhere tidy-repo is active — at the session Stop hook and on every PR — and
// costs ~nothing on a branch that is not this pass.
export const IMPROVE_COMMENTS_RUN = /^Claudinite tidy: improve comments/;

const isReadme = (p) => basename(p).toLowerCase() === 'readme.md';

const rule = {
  id: 'improve-comments-scope',
  severity: 'blocking',
  scope: 'work',
  doc: 'packs/tidy-repo/skills/improve-comments/SKILL.md',
  description: 'An improve-comments run changes only comments in code files, and README.md documents',
  why: 'the pass runs unattended against the repo\'s own source, and its whole safety case is that a comment cannot change behaviour — a run that also moved a line has made an unreviewed code change wearing a housekeeping title',

  run(work) {
    if (work.onDefaultBranch()) return [];
    if (!work.commits.some((m) => IMPROVE_COMMENTS_RUN.test(m))) return [];

    const deleted = new Set(work.deleted);
    return [...new Set([...work.changedFiles, ...work.deleted])]
      .filter((p) => (isReadme(p) ? deleted.has(p) : !commentOnly(p, work.readBase(p), work.read(p))))
      .sort()
      .map((p) => finding(rule, isReadme(p)
        ? {
          file: p,
          what: `an improve-comments run deleted ${p} — a README may be improved, never removed`,
          fix: 'restore the file; deciding a document should not exist is a change that gets reviewed, not a comment pass',
        }
        : unparseable(p)
          ? {
            file: p,
            what: `an improve-comments run changed ${p}, whose language the comment parser cannot read`,
            fix: `revert ${p} — outside the parser's set a file counts as code, so nothing here can show the change was only comments; leave them to a change that gets reviewed`,
          }
          : {
            file: p,
            what: work.readBase(p) === null || deleted.has(p)
              ? `an improve-comments run added or deleted ${p}, which is never a comment-only change`
              : `an improve-comments run changed more than the comments in ${p}`,
            fix: 'keep the branch to comment text in code files and to README.md content — a rename, a moved line or a reformat is its own change, with its own review',
          }));
  },
};

// Whether the file's language is one `commentOnly` can parse at all. Only used to
// pick the remedy: a run told "you changed more than comments" about a `.py` file
// it only commented would go looking for a code edit that isn't there.
function unparseable(p) {
  const dot = p.lastIndexOf('.');
  return !COMMENT_CHECKABLE.has(dot === -1 ? '' : p.slice(dot).toLowerCase());
}

export default [rule];

// tidy-repo task: improve-comments — the one tidy dimension whose subject is the
// repo's own source rather than its GitHub objects. The other three assess or act
// on issues, PRs and branches; this one reads a slice of the code AS COMMENTS and
// fixes what it finds there. Worker: task.md, which runs the improve-comments skill
// and nothing else.
//
// WHY IT IS A TASK AT ALL: a comment decays as the code around it changes and
// nothing makes it fail. No test goes red, no check fires, and no session working on
// something else will stop to fix one. The only way a repo's comments get read as
// comments is a pass whose whole job that is.
//
// WEEKLY. Comment drift is not latency-sensitive — a stale comment costs the next
// reader, whenever that is — and the window's commits are what name the files whose
// comments are likeliest wrong, so a weekly window is a bigger and better-targeted
// scope than a daily one for the same session cost.
//
// Self-contained (imports nothing): the whole contract is this default export.

// The pinned commit subject the run's own scope gate keys on, stated in task.md and
// enforced by the skill's `improve-comments-scope` check. Kept in step by the
// declaration test beside this pack's other tests.
const RUN_TITLE = 'Claudinite tidy: improve comments';

// How many of the window's changed files one round reads. A busy week can touch
// hundreds, and a session handed all of them skims; the rest are next round's, and
// the run says so rather than presenting a truncated list as the whole window.
const MAX_FILES = 40;

export default {
  id: 'improve-comments',
  frequency: 'weekly',                   // the weekly anchor (DESIGN §2); the window's commits are the scope
  precondition_signals: ['commits', 'prs'],
  agent_model: 'opus',                   // whether a comment carries a why the code cannot state is the judgment here, and a wrong call lands in the repo's source
  // Reviewed, never landed unattended. The scope check proves the diff is
  // comment-only, which is what makes the pass SAFE — it does not make the comments
  // themselves right, and a confidently wrong comment is the exact failure this task
  // exists to remove. A repo that wants these to land without review says so by
  // raising the ceiling here, in one line.
  expected_outcome: 'open-pr',
  agent_instructions: 'task.md',
  agent_execution_timeout: 1800,

  // Two gates, in order. Did anything land in the window — comments decay against
  // code, so a quiet week has nothing to re-read. Then: is this pass's previous PR
  // still open, in which case a second one would stack an unreviewed comment sweep
  // on an unreviewed comment sweep, over files the first one may already have
  // touched. Reading the pending PR's TITLE rather than a marker on the item means
  // a PR the owner opened by hand from this branch gates the round too.
  precondition(signals) {
    const openPrs = signals.prs?.open ?? [];
    const pending = openPrs.find((p) => String(p.title ?? '').startsWith(RUN_TITLE));
    if (pending) {
      return {
        run: false,
        reason: `PR #${pending.number} is this pass's previous round, still open — comments wait for its review rather than stack a second sweep on it`,
      };
    }

    const commits = signals.commits;
    if (!commits?.substantiveChange) {
      return { run: false, reason: 'no substantive commit in the window — nothing moved for a comment to have drifted from' };
    }
    const touched = commits.touchedPaths ?? [];
    if (!touched.length) {
      return { run: false, reason: 'the window\'s commits name no changed path — nothing to read' };
    }

    // A window can carry more files than one session should read as comments. Name
    // the cap and what it dropped rather than hand over a silently truncated list
    // that reads as the whole window.
    const scope = touched.slice(0, MAX_FILES);
    const dropped = touched.length - scope.length;
    return {
      run: true,
      reason: `${touched.length} path(s) changed in the window`,
      context: [
        `Read the comments in exactly these files, and no others: ${scope.join(', ')}.`,
        ...(dropped ? [`${dropped} further path(s) changed in the window and are NOT in scope this round — say so in the wrap-up so the next round is not read as a full sweep.`] : []),
        'A file whose comments are already right yields no edit — that is the common outcome and a good one.',
      ],
    };
  },
};
